INSERT INTO tours (id,title,slug,type,region,short_description,long_description,duration_days,duration_nights,transportation_type,visa_status,room_occupancy_label,single_room_supplement,single_room_supplement_currency,featured_home,featured_order,status,seo_title,seo_description,created_at,updated_at) VALUES ('10000000-0000-4000-8000-000000000001','Rusya Turu','rusya-turu','international','Avrupa','Moskova’nın görkemli meydanlarından St. Petersburg’un saraylarına uzanan bu özel programda Rusya’nın tarihini, sanatını ve mimarisini yakından keşfedin.','Rusya Turu; Moskova ve St. Petersburg’un öne çıkan tarihi, kültürel ve mimari duraklarını altı günlük kapsamlı bir programla bir araya getirir. Türk Hava Yolları uçuşları, iki şehir arasındaki Sapsan hızlı tren yolculuğu, dört yıldızlı oteller ve profesyonel rehberlik hizmetleriyle planlanan turda Rusya’nın simgesel meydanları, sarayları, müzeleri ve şehir yaşamı keşfedilir.',6,4,'mixed','visa-required','İki veya üç kişilik odada kişi başı',450,'EUR',0,5,'published','Rusya Turu 2026 | Moskova ve St. Petersburg | Mivatur','24–29 Ağustos 2026 Rusya Turu ile Moskova ve St. Petersburg’u keşfedin. THY uçuşları, Sapsan hızlı tren, 4 yıldızlı konaklama ve kapsamlı tur programı.','2026-08-19T00:00:00.000Z','2026-08-19T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET title=excluded.title,slug=excluded.slug,type=excluded.type,region=excluded.region,short_description=excluded.short_description,long_description=excluded.long_description,duration_days=excluded.duration_days,duration_nights=excluded.duration_nights,transportation_type=excluded.transportation_type,visa_status=excluded.visa_status,room_occupancy_label=excluded.room_occupancy_label,single_room_supplement=excluded.single_room_supplement,single_room_supplement_currency=excluded.single_room_supplement_currency,status='published',seo_title=excluded.seo_title,seo_description=excluded.seo_description,updated_at=excluded.updated_at;
