INSERT INTO tour_itinerary_days (id,tour_id,day_number,title,route,summary,description,highlights,transportation,accommodation,meals,created_at,updated_at) VALUES
('11000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001',1,'İstanbul’dan Moskova’ya Yolculuk','İstanbul → Moskova','İstanbul Havalimanı’ndan Moskova’ya uçuşun ardından panoramik şehir turu, Kızıl Meydan ve Kremlin ziyareti.','İstanbul Havalimanı Dış Hatlar Terminali Giden Yolcu Salonu’nda buluşuyoruz. Bagaj, bilet ve biniş işlemlerinin ardından Türk Hava Yolları’nın 07.15 seferiyle Moskova’ya hareket ediyoruz. Yerel saatle 11.05’te Moskova’ya varışımızın ardından havalimanında karşılanıyor ve özel aracımızla şehir merkezine transfer oluyoruz.\n\nPanoramik Moskova şehir turunda Rusya’nın kalbi olarak kabul edilen Kızıl Meydan’da Kremlin’i ve şehrin önemli simgelerini görüyoruz. UNESCO Dünya Mirası Listesi’nde bulunan Novodevichy Manastırı’nı dışarıdan görüyor, Serçe Tepeleri’nden Moskova’nın panoramik manzarasını izliyor ve Moskova Devlet Üniversitesi binasını görüyoruz. Gün içerisinde Poklonnaya Tepesi’nde bulunan Zafer Parkı’nı ziyaret ederek Rus tarihine dair bilgiler alıyoruz.\n\nÖğle yemeği için verilecek serbest zamanın ardından Kremlin ziyaretimizi gerçekleştiriyoruz. 1156 yılında ahşap bir kale olarak inşa edilen ve günümüzde Rusya Devlet Başkanı’nın resmî merkezi olan Kremlin’de kırmızı tuğlalı surları, tarihi kuleleri ve etkileyici katedralleri görüyoruz. Akşam yemeğinin ardından otelimize yerleşiyoruz.','["Kızıl Meydan","Kremlin","Novodevichy Manastırı","Serçe Tepeleri","Moskova Devlet Üniversitesi","Zafer Parkı"]','THY uçuşu + özel tur aracı','Novotel Moscow Centre veya benzeri 4 yıldızlı otel','Akşam yemeği','2026-08-19T00:00:00.000Z','2026-08-19T00:00:00.000Z'),
('11000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001',2,'Moskova’nın Sanat ve Tarih Durakları','Moskova','Moskova metrosu, Arbat Caddesi, Tretyakov Galerisi, Novodevichy Mezarlığı ve Moskova Merkez Camii.','Otelde alacağımız kahvaltının ardından Moskova Metro Turu ile programımıza başlıyoruz. Dünyanın en güzel metro sistemlerinden biri olarak kabul edilen Moskova metrosunda mozaikler, vitraylar, heykeller ve görkemli dekorasyonlarla süslenmiş Komsomolskaya, Kurskaya ve Kievskaya gibi önemli istasyonları görüyoruz.\n\nArdından Moskova’nın en eski caddelerinden biri olan Arbat Caddesi’nde yürüyüş turu gerçekleştiriyoruz. Tarihi yapıları, kafeleri, restoranları, Puşkin Evi’ni ve Rus kültürüne ait simgesel alanları görüyoruz. Sonrasında Rus sanatının en önemli koleksiyonlarından birine sahip Tretyakov Galerisi’ni ziyaret ediyor; Repin, Ayvazovski, Vasnetsov ve Şişkin gibi sanatçıların eserlerini görüyoruz.\n\nÖğle yemeği için verilecek serbest zamanın ardından Anton Çehov ve Nikolay Gogol gibi önemli isimlerin mezarlarının bulunduğu Novodevichy Mezarlığı’nı ziyaret ediyoruz. Günün sonunda 10.000 kişilik kapasitesiyle Avrupa’nın en büyük camilerinden biri olan Moskova Merkez Camii’ni geziyoruz. Akşam yemeğinin ardından otelimize dönüyoruz.','["Moskova Metrosu","Komsomolskaya İstasyonu","Kurskaya İstasyonu","Kievskaya İstasyonu","Arbat Caddesi","Tretyakov Galerisi","Novodevichy Mezarlığı","Moskova Merkez Camii"]','Metro + özel tur aracı','Novotel Moscow Centre veya benzeri 4 yıldızlı otel','Kahvaltı ve akşam yemeği','2026-08-19T00:00:00.000Z','2026-08-19T00:00:00.000Z'),
('11000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000001',3,'Sapsan Treni ile St. Petersburg’a Geçiş','Moskova → St. Petersburg','Sapsan hızlı treniyle St. Petersburg’a geçiş ve şehrin önemli simgelerini kapsayan panoramik tur.','Kahvaltının ardından otelden çıkış yapıyor ve tren garına transfer oluyoruz. Sapsan hızlı treni ile St. Petersburg’a hareket ediyoruz. Varışımızın ardından panoramik şehir turumuza başlıyoruz.\n\nNevsky Prospect boyunca ilerlerken St. Petersburg’un görkemli mimarisini keşfediyoruz. Kazan Katedrali’ni, Rus Çarlarının eski ikametgâhı olan Kışlık Saray’ı ve Hermitage çevresini görüyoruz. Turumuz Vasilevskiy Adası, St. Isaac Katedrali ve şehrin kuruluş noktası olan Peter ve Paul Kalesi ile devam ediyor.\n\nSenato Meydanı’nda bulunan Bronz Atlı heykelini ve şehrin kalbi sayılan Saray Meydanı’nı ziyaret ediyoruz. Akşam yemeğinin ardından otelimize transfer oluyoruz.','["Nevsky Prospect","Kazan Katedrali","Kışlık Saray","Hermitage çevresi","Vasilevskiy Adası","St. Isaac Katedrali","Peter ve Paul Kalesi","Senato Meydanı","Bronz Atlı","Saray Meydanı"]','Sapsan hızlı tren + özel tur aracı','Novotel Saint Petersburg Centre veya benzeri 4 yıldızlı otel','Kahvaltı ve akşam yemeği','2026-08-19T00:00:00.000Z','2026-08-19T00:00:00.000Z'),
('11000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000001',4,'Çarlık Sarayları ve Peterhof','St. Petersburg','Puşkin bölgesindeki Çariçe Sarayı, Amber Odası ve Peterhof Sarayı gezisi.','Kahvaltının ardından Puşkin bölgesine hareket ediyoruz. Çarlık döneminin en görkemli yazlık saraylarından biri olan Çariçe Sarayı’nı ziyaret ediyor ve dünyaca ünlü Amber Odası’nı görüyoruz. İkinci Dünya Savaşı sırasında büyük zarar gören ve uzun restorasyon çalışmalarının ardından yeniden eski ihtişamına kavuşan sarayın salonlarını geziyoruz. Sarayın etkileyici parkında yürüyüş yaptıktan sonra öğle yemeği için serbest zaman veriyoruz.\n\nArdından Rus Versailles’ı olarak anılan Peterhof Sarayı ve Parkı’na geçiyoruz. Zarif bahçeleri, görkemli çeşmeleri ve Finlandiya Körfezi manzarasını keşfediyoruz. Büyük Saray’ın ihtişamlı salonlarını gezerken Rus İmparatorluk ailesinin yaşamı hakkında bilgi alıyoruz. Gün sonunda akşam yemeğinin ardından otelimize dönüyoruz.','["Puşkin Bölgesi","Çariçe Sarayı","Amber Odası","Çariçe Sarayı Parkı","Peterhof Sarayı","Peterhof Bahçeleri","Finlandiya Körfezi"]','Özel tur aracı','Novotel Saint Petersburg Centre veya benzeri 4 yıldızlı otel','Kahvaltı ve akşam yemeği','2026-08-19T00:00:00.000Z','2026-08-19T00:00:00.000Z'),
('11000000-0000-4000-8000-000000000005','10000000-0000-4000-8000-000000000001',5,'Hermitage Müzesi ve Neva Nehri','St. Petersburg','Hermitage Müzesi, St. Petersburg Merkez Camii ve Neva Nehri tekne turu.','Kahvaltının ardından otelden çıkış yapıyor ve dünyanın en önemli müzelerinden biri olan Hermitage Müzesi’ni ziyaret ediyoruz. Rus Çarlarının eski sarayı olan Kışlık Saray içerisinde Leonardo da Vinci, Raphael ve birçok önemli sanatçının eserlerini görme fırsatı buluyoruz. Müzenin Antik Yunan, Doğu ve Mısır sanatına ait zengin koleksiyonlarını ziyaret ediyoruz.\n\nÖğle yemeği için verilecek serbest zamanın ardından St. Petersburg Merkez Camii’ni ziyaret ediyoruz. Uzun yıllar süren inşası ve Sovyet döneminde depo olarak kullanılmasıyla dikkat çeken yapı, Avrupa’nın en büyük ve etkileyici camilerinden biri olarak kabul edilmektedir.\n\nGünün son bölümünde Neva Nehri ve şehrin kanalları üzerinde tekne turu gerçekleştiriyoruz. Kuzey’in Venedik’i olarak anılan şehirde tarihi köprüleri, kanalları, St. Isaac Katedrali’ni ve Kanlı Kilise gibi önemli yapıları su üzerinden görme fırsatı buluyoruz. Turumuzun ardından havalimanına transfer oluyoruz.','["Hermitage Müzesi","Kışlık Saray","St. Petersburg Merkez Camii","Neva Nehri","Şehir kanalları","St. Isaac Katedrali","Kanlı Kilise"]','Özel tur aracı + tekne','Gece uçuşu nedeniyle otel konaklaması bulunmuyor','Kahvaltı ve akşam yemeği','2026-08-19T00:00:00.000Z','2026-08-19T00:00:00.000Z'),
('11000000-0000-4000-8000-000000000006','10000000-0000-4000-8000-000000000001',6,'İstanbul’a Dönüş','St. Petersburg → İstanbul','Türk Hava Yolları uçuşuyla İstanbul’a dönüş.','Türk Hava Yolları’nın 00.15 seferi ile İstanbul’a hareket ediyoruz. Saat 04.15’te İstanbul Havalimanı’na varışımızla organizasyonumuz sona eriyor. Bir başka Mivatur gezisinde buluşmak üzere vedalaşıyoruz.','["St. Petersburg Havalimanı","İstanbul Havalimanı"]','Türk Hava Yolları uçuşu','Bulunmuyor','Bulunmuyor','2026-08-19T00:00:00.000Z','2026-08-19T00:00:00.000Z');
