INSERT INTO tour_important_notes (id,tour_id,title,content,sort_order,created_at,updated_at) VALUES
('14000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Vize ve pasaport','Rusya turu için bordo pasaport sahiplerinin vize alması gerekmektedir. Tur bilgilerinde belirtilen vize ve hizmet bedeli 100 €’dur. Yeşil pasaport sahipleri için vize gerekmemektedir. Pasaport geçerlilik süresi ve güncel giriş koşulları rezervasyon öncesinde ayrıca kontrol edilmelidir.',0,'2026-08-19T00:00:00.000Z','2026-08-19T00:00:00.000Z'),
('14000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001','Uçuş ve bagaj','Uçuş saatleri, havayolu ve bagaj hakları kesin operasyon planıyla birlikte bildirilir.',1,'2026-08-19T00:00:00.000Z','2026-08-19T00:00:00.000Z'),
('14000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000001','İptal ve değişiklik','Değişiklik ve iptal koşulları rezervasyon öncesinde paylaşılan sözleşme ve tur özelindeki şartlara göre değerlendirilir.',2,'2026-08-19T00:00:00.000Z','2026-08-19T00:00:00.000Z'),
('14000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000001','Tur programı notları','Program sırası; hava, ulaşım ve operasyon koşulları nedeniyle içerik korunarak değişebilir.',3,'2026-08-19T00:00:00.000Z','2026-08-19T00:00:00.000Z');
INSERT INTO tour_faqs (id,tour_id,question,answer,sort_order,published,created_at,updated_at) VALUES
('15000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Rusya Turu için vize gerekiyor mu?','Bordo pasaport sahiplerinin vize alması gerekmektedir. Yeşil pasaport sahipleri için vize gerekmemekle birlikte güncel giriş koşulları rezervasyon öncesinde kontrol edilmelidir.',0,1,'2026-08-19T00:00:00.000Z','2026-08-19T00:00:00.000Z'),
('15000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001','Moskova ile St. Petersburg arasında ulaşım nasıl sağlanıyor?','İki şehir arasındaki ulaşım Sapsan hızlı treninde 2. sınıf biletle sağlanmaktadır.',1,1,'2026-08-19T00:00:00.000Z','2026-08-19T00:00:00.000Z'),
('15000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000001','Turda kaç gece konaklama bulunuyor?','Moskova’da 2 ve St. Petersburg’da 2 gece olmak üzere toplam 4 gece dört yıldızlı otel konaklaması bulunuyor.',2,1,'2026-08-19T00:00:00.000Z','2026-08-19T00:00:00.000Z');
